				this.upLoaidng = true;
				return true;
			},
			handleVideoSuccess(res, file) {
				this.upLoaidng = false;
				let { code, msg, obj } = res;
				if (code == '00') {
					let urls = obj.split('#');
					this.form.url = urls[0]; 
					this.$message({
						type: 'success',
						message: '上传成功',
					});


