			   			...{
			   				link: parent.getAttribute('href'),
			   				target:parent.getAttribute('target')?parent.getAttribute('target'):'_self'
			   			}
			   		};

			   }else{

			   	this.form = {
			   		...this.form,
			   		...{
			   			link:'',
			   			target:''
			   		}
			   	}
			   }

			}

