		<CutImg
  		v-bind:is-show.sync="isShow"
  		v-bind:img-url="imgUrl"
  		v-bind:call-back="initStep"
  		v-bind:file-name="fileName"
  		v-bind:file-type="fileType"
  		v-bind:fixed-number="fixedNumber"
