// 判断机型是否是安卓机型，不然就是苹果机型
var u = navigator.userAgent;
var isAndroid = u.indexOf('Android') > -1 || u.indexOf('Adr') > -1; //android终端 var music = $('#music')[0];// html的audio获取元素

var sound = PIXI.sound.Sound.from({// 用pixi-sound载入音乐,用于安卓
url: 'music.mp3',
loop: true
});
$('.music-start').on('click', function() {//停止音乐
$(this).addClass('displayNone');// 对于class的左右可以无视
$('.music-stop').removeClass('displayNone');
if(isAndroid) {
// 安卓
sound.stop();
} else {
// ios
music.pause();
}

})
$('.music-stop').on('click', function() {//播放音乐
$(this).addClass('displayNone');// 对于class的左右可以无视
$('.music-start').removeClass('displayNone');
if(isAndroid) {
// 安卓
sound.play();
} else {
// ios
music.play();
}
})
//初始化执行
if(isAndroid) {
// 安卓
sound.play();
} else if(isiOS) {
// ios
    music.play();
document.addEventListener("WeixinJSBridgeReady", function () {
music.play();
}, false);
}

