"height\":280},{\"nodeType\":\"tip\",\"x\":267,\"y\":100,\"width\":150,\"text\":\"词法环境是静态的\\n\",\"attr\":{\"borderColor\":\"#7EC8CE\",\"color\":\"#fff\",\"fillColor\":\"#585DCB\",\"dashed\":false,\"titleId\":\"166263594488787192961\"},\"id\":\"166210766259245344784\",\"nodeId\":\"166263594488784513253\",\"height\":28},{\"id\":\"166210826856657893041\",\"nodeId\":\"166263594488733718521\",\"nodeType\":\"node\",\"x\":615,\"y\":123,\"text\":\"词法作用域\",\"attr\":{\"borderColor\":\"#3c3c3c\",\"color\":\"#333\",\"fillColor\":\"#eee\",\"dashed\":false,\"titleId\":\"166263594488748100327\"}},{\"nodeType\":\"tip\",\"x\":734,\"y\":119,\"width\":150,\"text\":\"词法作用域是由你在写代码\\n时将变量和块作用域写在哪\\n里来决定的\",\"attr\":{\"borderColor\":\"#7EC8CE\",\"color\":\"#fff\",\"fillColor\":\"#585DCB\",\"dashed\":false,\"titleId\":\"166263594488793291855\"},\"id\":\"166210829465321788007\",\"nodeId\":\"166263594488756364387\",\"height\":42},{\"nodeType\":\"tip\",\"x\":737,\"y\":189,\"width\":150,\"text\":\"JavaScript 并不具有动态作\\n用域。它只有词法作用域，\\n简单明了。 但是 this 机制\\n某种程度上很像动态作用域\\n。\",\"attr\":{\"borderColor\":\"#7EC8CE\",\"color\":\"#fff\",\"fillColor\":\"#585DCB\",\"dashed\":false,\"titleId\":\"166263594488726771602\"},\"id\":\"166210835853771709617\",\"nodeId\":\"166263594488786235998\",\"height\":70},{\"id\":\"166210836247694147712\",\"nodeId\":\"166263594488786566909\",\"nodeType\":\"node\",\"x\":616,\"y\":183,\"text\":\"动态作用域\",\"attr\":{\"borderColor\":\"#3c3c3c\",\"color\":\"#333\",\"fillColor\":\"#eee\",\"dashed\":false,\"titleId\":\"1662635944887824404\"}},{\"nodeType\":\"tip\",\"x\":739,\"y\":282,\"width\":150,\"text\":\"主要区别：词法作用域是在\\n写代码或者说定义时确定的\\n，而动态作用域是在运行时\\n确定的。(this 也是!)\\n\\n词法作用域关注函数在 何处\\n声明，而动态作用域关注函\\n数从何处调用。\",\"attr\":{\"borderColor\":\"#7EC8CE\",\"color\":\"#fff\",\"fillColor\":\"#585DCB\",\"dashed\":false,\"titleId\":\"166263594488835439550\"},\"id\":\"166210841233834158724\",\"nodeId\":\"166263594488861882837\",\"height\":112},{\"nodeType\":\"tip\",\"x\":910,\"y\":119,\"width\":