/** debounce防抖 */
import debounce from "lodash.debounce";

export default {
  props: {
    threshold: {
      type: Number,
      default: 100
    }
  },

  data() {
    return {
      scrollTop: null
    };
  },

  mounted() {
    this.gotop_plus_log(
      this.$goTopPlusAppDescription +
        " ➡️ " +
        this.$goTopPlusAppName +
        " ➡️ " +
        this.$goTopPlusAppUrl
    );

    if (!this.options.mobileShow && !this.isPC()) {
      // 手机端不显示
      return;
    }
    this.scrollTop = this.getScrollTop();
    // `debounce`将多个触发事件的操作延迟到最后一次触发执行，在性能上做了一定的优化
    window.addEventListener(
      "scroll",
      debounce(() => {
        this.scrollTop = this.getScrollTop();
      }, 100)
    );
  },

  methods: {
    /** 判断是否是电脑端访问 */
    isPC() {
      let userAgentInfo = navigator.userAgent || "";
      const Agents = [
        "Android",
        "iPhone",
        "SymbianOS",
        "Windows Phone",
        "iPad",
        "iPod"
      ];
      let flag = true;
      for (let v = 0; v < Agents.length; v++) {
        if (userAgentInfo.indexOf(Agents[v]) > 0) {
          flag = false;
          break;
        }
      }
      return flag;
    },
    getScrollTop() {
      return (
        window.pageYOffset ||
        document.documentElement.scrollTop ||
        document.body.scrollTop ||
        0
      );
    },

    scrollToTop() {
      window.scrollTo({ top: 0, behavior: "smooth" });
      this.scrollTop = 0;
    },
    // 统一输出日志
    gotop_plus_log(str = this.options.pluginName) {
      if (this.options.log) {
        console.log && console.log(str);
      }
    }
  },

  computed: {
    // 获取插件配置
    options() {
      return {
        // 是否在移动设备上显示(default: true)
        mobileShow: false,
        // 回到页首元素显示触发的高度阈值(default: 50)
        threshold: 50
      }
      // return JSON.parse
      //   ? JSON.parse(GO_TOP_PLUS_PLUGIN_OPTIONS)
      //   : GO_TOP_PLUS_PLUGIN_OPTIONS;
    },
    show() {
      return this.scrollTop > this.options.threshold;
    }
  }
};

