          _this.img_height = this.height;

          //初始化
          (_this.scaleBase = 1),
            (_this.scaleX = 1),
            (_this.scaleY = 1),
            (_this.old_bg_width = 0);
          _this.init_translateX = -1;

          _this.initBgImgPosition();
          _this.base64 = base64;
        };
        img.src = base64;
      };
      reader.readAsDataURL(file);
