        var img_rate = this.img_width / this.img_height;
        if (cropper_rate >= img_rate) {
          //以图片高度显示全为准
          // console.log('以高度比例为准')
          var scale_rate = this.cropper_height / this.img_height;
        } else {
          // console.log('以宽度比例为准')

          var scale_rate = this.cropper_width / this.img_width;
          // console.log('初始图片尺寸与原图比例：'+scale_rate);
