			showPre:function(url,editIndex){

				if(!this.isCut){
					return false;
				}

				this.editLoading = this.$loading({
		          lock: true,
		          text: 'Loading',
		          spinner: 'el-icon-loading',
		          background: 'rgba(0, 0, 0, 0.7)'
		        });


				this.editIndex = editIndex;

				var _this = this;
				var i = new Image();
				i.onload = function(){

					let w = i.width;
					let h = i.height;

					let canvas = document.createElement('canvas');
					let ctx = canvas.getContext('2d');
					canvas.width = w;
					canvas.height = h;

					ctx.drawImage(i,0,0);

					try{

