};
Collect.prototype.updateByDomPosTop = function() {

	//根据距body的距离进行减分 数值越大 减得越多 以50为单位
	//
	for (var i = 0; i < this.allNode.length; i++) {
		if(this.allNode[i].domPosTop){
			this.allNode[i].score -=(this.allNode[i].domPosTop/50);
		}

