          console.log(rect);

          //开始缩放图片 单位是px
          var layH = rect.height;
          var layW = rect.width; 

          console.log(this.data.mode);

          if(this.data.mode == 'heighFix'){
             var rate = layH/this.data.img.height;
             console.log(rate); 
             this.setData({
              styleAttr:{
                height:layH,
                width:this.data.img.width*rate,
                top:0,
                left:this.data.img.width*rate>layW?(layW-this.data.img.width*rate)*0.5:0
              }
             })
          }else{

            var rate = layW/this.data.img.width;
            console.log(rate); 
            this.setData({
             styleAttr:{
               height:this.data.img.height*rate,
               width:layW,
               top:this.data.img.height*rate>layH?(layH-this.data.img.height*rate)*0.5:0,
               left:0
             }
            })
          }


          this.setData({
            finished:true
          })

        }).exec(); 

    },
    mInit:function(v){
      if(v){
        this.setData({
          mode:v
        })
      }

      console.log(this.data.mode);

    },
    init:function(v){
      console.log(v);
      if(v.indexOf('%')>-1){  //按百分比

        this.setData({
          holderPadding:v
        })

        console.log(this.data.holderPadding);

      }else{  //固定数值 按rpx单元
        this.setData({
          imgShowH:v+'rpx',
          holderPadding:'0'
        })
      }

    }
  },
  attached() {  //在组件完全初始化完毕
    this.setData({
      id:parseInt(Math.random()*10000)
    })
